-- EMON RESELLER PANEL live catalog setup
-- Before running: replace admin@example.com in both policy definitions with the exact email of your one Supabase Auth admin user.
-- This SQL seeds the current 66-product catalog. Run once in Supabase SQL Editor.
create table if not exists public.site_catalog (
  id integer primary key check (id = 1),
  products jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.site_catalog enable row level security;
revoke all on table public.site_catalog from anon, public;
revoke all on table public.site_catalog from authenticated;
grant select on table public.site_catalog to anon, authenticated;
grant update on table public.site_catalog to authenticated;
drop policy if exists "Anyone can read catalog" on public.site_catalog;
drop policy if exists "Only owner admin can update catalog" on public.site_catalog;
create policy "Anyone can read catalog" on public.site_catalog for select using (true);
create policy "Only owner admin can update catalog" on public.site_catalog for update to authenticated
using ((auth.jwt() ->> 'email') = 'admin@example.com')
with check ((auth.jwt() ->> 'email') = 'admin@example.com');
